84	
85		i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);
86		switch (num_msgs) {
87		case 1:
88			if (msgs[0].flags & I2C_MSG_READ) {
89				LOG_ERR("Unexpected read");
90				return -EIO;
91			}
92	
93			if (msgs[0].len != 3) {
94				LOG_ERR("Unexpected msg0 length %d", msgs->len);
95				return -EIO;
96			}
97	
98			ret = emul_sy24561_reg_write(target, *msgs[0].buf, sys_get_be16(msgs[0].buf + 1));
99			if (ret) {
100				LOG_ERR("emul_sy24561_reg_write returned %d", ret);
101			}
102			break;
103		case 2:
104			if (msgs[0].flags & I2C_MSG_READ) {
105				LOG_ERR("Unexpected read");
106				return -EIO;
107			}
108			if (msgs[0].len != 1) {
109				LOG_ERR("Unexpected msg0 length %d", msgs[0].len);
110				return -EIO;
111			}
112	
113			if (msgs[1].flags & I2C_MSG_WRITE) {
114				LOG_ERR("Unexpected write");
115				return -EIO;
116			}
117			if (msgs[1].len != 2) {
118				LOG_ERR("Unexpected msg1 length %d", msgs[1].len);
119				return -EIO;
120			}
121	
122			uint16_t val;
123	
124			ret = emul_sy24561_reg_read(target, *msgs[0].buf, &val);
125			if (ret) {
126				LOG_ERR("emul_sy24561_reg_read returned %d", ret);
127				return ret;
128			}
129	
130			sys_put_be16(val, msgs[1].buf);
131			break;
132		default:
133			LOG_ERR("Invalid number of messages: %d", num_msgs);
134			return -EIO;
135		}
136	
137		return ret;
