11	#define BK7258_GPIO_FUNC_MODE_BASE  0x440100C0U
12	
13	#define BK_GPIO_CFG_OFF(gpio)       ((gpio) * 4U)
14	#define BK_GPIO_BIT_2ND_FUNC        BIT(6)
15	#define BK_GPIO_BIT_PULL_MODE_EN    BIT(5)
16	#define BK_GPIO_BIT_PULL_MODE       BIT(4)
17	#define BK_GPIO_BIT_OUTPUT_EN       BIT(3) /* Active low */
18	#define BK_GPIO_BIT_INPUT_EN        BIT(2)
19	
20	int pinctrl_configure_pins(const pinctrl_soc_pin_t *pins, uint8_t pin_cnt, uintptr_t reg)
21	{
22		ARG_UNUSED(reg);
23	
24		for (uint8_t i = 0; i < pin_cnt; i++) {
25			pinctrl_soc_pin_t p = pins[i];
26			uint8_t gpio = p & 0x3f;
27			uint8_t func = (p >> 8) & 0x0f;
28			uint32_t val;
29	
30			val = sys_read32(BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
31	
32			if (p & BK7258_FLAG_SECOND_FUNC) {
33				val |= BK_GPIO_BIT_2ND_FUNC;
34			}
35			if (p & BK7258_FLAG_OUTPUT) {
36				val &= ~BK_GPIO_BIT_OUTPUT_EN;
37			}
38			if (p & BK7258_FLAG_INPUT) {
39				val |= BK_GPIO_BIT_INPUT_EN;
40			}
41			if (p & BK7258_FLAG_PULL_UP) {
42				val |= BK_GPIO_BIT_PULL_MODE_EN | BK_GPIO_BIT_PULL_MODE;
43			}
44			if (p & BK7258_FLAG_PULL_DOWN) {
45				val |= BK_GPIO_BIT_PULL_MODE_EN;
46				val &= ~BK_GPIO_BIT_PULL_MODE;
47			}
48	
49			sys_write32(val, BK7258_GPIO_CFG_BASE + BK_GPIO_CFG_OFF(gpio));
50	
51			uint8_t group = gpio / 8;
52			uint8_t shift = (gpio % 8) * 4;
53			uint32_t addr = BK7258_GPIO_FUNC_MODE_BASE + group * 4;
54			uint32_t fval = sys_read32(addr);
55	
56			fval &= ~(0x0fU << shift);
57			fval |= ((uint32_t)func << shift);
58			sys_write32(fval, addr);
59		}
60	
61		return 0;
62	}
